def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos] == " ":
            pos += 1

    def parse_expr() -> int:
        val = parse_term()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "+-":
                op = expr[pos]
                pos += 1
                rhs = parse_term()
                if op == "+":
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_term() -> int:
        val = parse_unary()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "*/%":
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == "*":
                    val *= rhs
                elif op == "/":
                    if rhs == 0:
                        raise ZeroDivisionError
                    q = abs(val) // abs(rhs)
                    val = -q if (val < 0) ^ (rhs < 0) else q
                else:
                    if rhs == 0:
                        raise ZeroDivisionError
                    r = abs(val) % abs(rhs)
                    val = -r if val < 0 else r
            else:
                break
        return val

    def parse_unary() -> int:
        nonlocal pos
        neg = False
        while True:
            skip_spaces()
            if pos < n and expr[pos] == "-":
                neg = not neg
                pos += 1
            else:
                break
        val = parse_primary()
        skip_spaces()
        if pos < n and expr[pos] == "^":
            stack: list[tuple[bool, int]] = []
            while pos < n and expr[pos] == "^":
                pos += 1
                rneg = False
                while True:
                    skip_spaces()
                    if pos < n and expr[pos] == "-":
                        rneg = not rneg
                        pos += 1
                    else:
                        break
                rbase = parse_primary()
                stack.append((rneg, rbase))
                skip_spaces()
            cur = stack[-1][1]
            if stack[-1][0]:
                cur = -cur
            for i in range(len(stack) - 2, -1, -1):
                rneg, rbase = stack[i]
                if cur < 0:
                    raise ValueError
                cur = pow(rbase, cur)
                if rneg:
                    cur = -cur
            if cur < 0:
                raise ValueError
            val = pow(val, cur)
        return -val if neg else val

    def parse_primary() -> int:
        nonlocal pos
        skip_spaces()
        if expr[pos] == "(":
            pos += 1
            val = parse_expr()
            skip_spaces()
            pos += 1
            return val
        start = pos
        while pos < n and "0" <= expr[pos] <= "9":
            pos += 1
        num_str = expr[start:pos]
        if len(num_str) <= 4000:
            return int(num_str)
        val = 0
        for k in range(0, len(num_str), 1000):
            chunk = num_str[k : k + 1000]
            val = val * (10 ** len(chunk)) + int(chunk)
        return val

    try:
        return parse_expr()
    except (ZeroDivisionError, ValueError):
        return "error"
